    fun getCitiesForState(stateCode: String?): List<String> {
        if (stateCode.isNullOrBlank() || stateCode.equals("ALL", ignoreCase = true)) {
            return listOf("Todas as Cidades") + BRAZILIAN_CITIES
        }
        return CITIES_BY_BRAZILIAN_STATE[stateCode.uppercase()] ?: (listOf("Todas as Cidades") + BRAZILIAN_CITIES)
    }

    fun getCitiesForCountry(countryCode: String?): List<String> {
        if (countryCode.isNullOrBlank() || countryCode.equals("ALL", ignoreCase = true)) {
            return BRAZILIAN_CITIES
        }
        return GLOBAL_CITIES_BY_COUNTRY[countryCode.uppercase()] ?: BRAZILIAN_CITIES
    }

